  q: 'El artículo 560 C.P. tipifica como delito de desórdenes públicos los daños que se produzcan en determinadas infraestructuras entre las que no se encuentran:',
  o: { a: 'Las líneas de telecomunicaciones.', b: 'Las vías férreas.', c: 'Las carreteras.', d: 'Las conducciones de gas.' },
